const translatedText=new WeakMap(),translatedAttributes=new WeakMap();
const privateText='#language-select option,.user-widget-text,.user-profile-text,.list-name,.list-url,.tab-title,.tab-resource strong,.vault-entry strong,.vault-entry small,.save-offer>p:not(.note),#toast,pre,script,style,textarea,#folder-filter option:not([value=""]),#bookmark-folders,.bookmark-bar-item span,.tab-search-row strong,.tab-search-row small,.reader-article,.user-shortcut-title';
function translateUI(){
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;
 while((node=walker.nextNode())){
  if(!node.parentElement||node.parentElement.closest(privateText)||!node.nodeValue.trim())continue;
  let stored=translatedText.get(node);if(!stored||node.nodeValue!==stored.output)stored={source:node.nodeValue};
  const output=tr(stored.source);if(node.nodeValue!==output)node.nodeValue=output;
  stored.output=output;translatedText.set(node,stored);
 }
 for(const element of document.querySelectorAll('[title],[placeholder],[aria-label]')){
  if(element.classList.contains('tab'))continue;
  let values=translatedAttributes.get(element);if(!values){values={};translatedAttributes.set(element,values)}
  for(const attribute of ['title','placeholder','aria-label']){
   if(!element.hasAttribute(attribute))continue;const currentValue=element.getAttribute(attribute);let stored=values[attribute];
   if(!stored||currentValue!==stored.output)stored={source:currentValue};
   const output=tr(stored.source);if(currentValue!==output)element.setAttribute(attribute,output);
   stored.output=output;values[attribute]=stored;
  }
 }
}
let translationQueued=false;
new MutationObserver(()=>{if(!translationQueued){translationQueued=true;queueMicrotask(()=>{translationQueued=false;translateUI()})}}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['title','aria-label','placeholder']});
let openingTimer;
function startOpeningAnimation(){
 const boot=$('#boot-screen');clearTimeout(openingTimer);
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){boot.hidden=true;document.body.classList.remove('app-opening');return}
 boot.hidden=false;document.body.classList.remove('app-opening');void boot.offsetWidth;document.body.classList.add('app-opening');
 openingTimer=setTimeout(()=>{boot.hidden=true;document.body.classList.remove('app-opening')},1000);
}
window.veyra.onOpened(startOpeningAnimation);

function preferredBrowser(){return state.browsers.find(b=>b.id===state.settings.externalBrowser)||state.browsers[0]}
function externalGoogleView(blocked=false){const browser=preferredBrowser();return `<div class="page google-page animate-in"><div class="google-heading">${icon('globe')}<h1>${blocked?'Google ограничил встроенный вход':'Сервисы Google'}</h1></div><p class="sub">${blocked?'Открой весь сайт в полноценном браузере, чтобы войти в аккаунт.':'Открывай сервисы в полноценном браузере с сохранением входа.'}</p><div class="card inset"><label class="field">Браузер<select id="external-browser" aria-label="Браузер">${state.browsers.map(b=>`<option value="${b.id}" ${browser?.id===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><p class="note">${browser?.chromium?'Используется отдельный профиль Veyra. Вход сохраняется в этом браузере.':'Firefox откроется в своём текущем профиле.'}</p>${blocked?`<button class="primary" data-action="open-external">${icon('arrow')} ${esc(tr('Открыть в браузере'))}${browser?' · '+esc(browser.name):''}</button>`:''}</div>${!blocked?`<div class="service-grid">${[['youtube','YouTube','play'],['gmail','Gmail','mail'],['drive','Google Drive','folder'],['account','Google Account','lock'],['search','Google','search']].map(([id,label,i])=>`<button data-google-service="${id}"><span>${icon(i)}</span><strong>${label}</strong>${icon('arrow')}</button>`).join('')}</div>`:''}<div class="profile-notice">${icon('info')}<span>Это отдельное окно другого браузера. Вход не переносится во вкладки Veyra; её настройки приватности в этом окне не применяются.</span></div>${blocked?'<button class="text-button wide" data-url="veyra://google">Выбрать другой сервис или браузер</button>':''}</div>`}
function customizeView(){const s=state.settings;const themes=[['violet','Фиолетовая','#bc9ffa'],['ocean','Голубая','#85bdf5'],['forest','Зелёная','#8ad4b2'],['rose','Розовая','#efa3c3'],['amber','Янтарная','#efc28b']];return `<p class="sub">Настрой внешний вид под себя.</p><button class="secondary wide" data-panel="shortcuts">Ярлыки главной</button><div class="section">ОФОРМЛЕНИЕ</div><div class="segmented">${[['dark','Тёмное'],['light','Светлое'],['system','Системное']].map(([id,label])=>`<button data-theme-mode="${id}" class="${s.theme===id?'active':''}" aria-pressed="${s.theme===id}">${tr(label)}</button>`).join('')}</div><div class="section">ЦВЕТ</div><div class="theme-swatches">${themes.map(([id,label,color])=>`<button data-color-theme="${id}" class="swatch swatch-${id} ${s.colorTheme===id?'active':''}" title="${tr(label)}" aria-label="${tr(label)}" aria-pressed="${s.colorTheme===id}">${s.colorTheme===id?icon('check'):''}</button>`).join('')}</div><label class="color-picker">Свой цвет<input id="custom-accent" type="color" value="${esc(s.customAccent)}" aria-label="Свой цвет"></label><div class="section">ОБОИ</div><div class="wallpaper-grid">${[['none','Без обоев'],['aurora','Сияние'],['dusk','Закат'],['ocean','Океан'],['forest','Лес']].map(([id,label])=>`<button data-wallpaper="${id}" class="wallpaper-tile wallpaper-${id} ${s.wallpaper===id?'active':''}" aria-pressed="${s.wallpaper===id}"><span>${tr(label)}</span>${s.wallpaper===id?icon('check'):''}</button>`).join('')}</div><button class="secondary wide" data-action="wallpaper-pick">${icon('upload')} Выбрать своё изображение</button>${s.wallpaper==='custom'?'<button class="text-button wide" data-action="wallpaper-remove">Удалить своё изображение</button>':''}<label class="field">Затемнение<input type="range" id="wallpaper-dim" min="0" max="85" step="5" value="${s.wallpaperDim}"></label><p class="note">Изображение хранится только на этом компьютере.</p><button class="text-button wide" data-url="veyra://settings">Все настройки</button>`}
let tabQuery='';
function tabRows(){const query=tabQuery.toLocaleLowerCase();const rows=state.tabs.filter(t=>`${t.title} ${t.url}`.toLocaleLowerCase().includes(query));return rows.map(t=>`<div class="tab-search-row ${t.id===state.selected?'active':''}"><button data-select-tab="${t.id}"><span>${icon(t.pinned?'pin':t.sleeping?'moon':'globe')}</span><span><strong>${esc(t.url.startsWith('veyra:')?tr(t.title):t.title)}</strong><small>${esc(t.url)}</small></span></button><button class="small-icon" data-close-tab="${t.id}" aria-label="Закрыть вкладку">${icon('close')}</button></div>`).join('')||'<div class="empty">Ничего не найдено.</div>'}
function tabSearchView(){return `<input class="find-input" id="tab-query" value="${esc(tabQuery)}" placeholder="Поиск по вкладкам" aria-label="Поиск по вкладкам"><div id="tab-results">${tabRows()}</div><button class="secondary wide" data-action="restore-closed" ${!state.closedTabs?'disabled':''}>${icon('history')} Восстановить закрытую вкладку</button>`}
function readerView(){const t=current(),article=t.reader;return `<div class="reader-toolbar"><button class="secondary" data-action="reader">${icon('back')} Назад к странице</button><div class="zoom-controls"><button class="small-icon" data-action="zoom-out" aria-label="Уменьшить">${icon('minus')}</button><span>${Math.round(Math.pow(1.2,t.zoomLevel||0)*100)}%</span><button class="small-icon" data-action="zoom-in" aria-label="Увеличить">${icon('plus')}</button></div></div><article class="reader-article"><p class="reader-source">${esc(safeOrigin(article.url))}</p><h1>${esc(article.title)}</h1>${article.blocks.map(block=>{const tag=['h1','h2','h3','li','blockquote'].includes(block.tag)?block.tag:'p';return `<${tag}>${esc(block.text)}</${tag}>`}).join('')}</article>`}
function helpView(){return `<div class="shortcut-reference">${[['Ctrl + L','Адресная строка'],['Ctrl + T','Новая вкладка'],['Ctrl + Shift + T','Восстановить закрытую вкладку'],['Ctrl + Shift + A','Поиск по вкладкам'],['Ctrl + D','Добавить в закладки'],['Ctrl + F','Найти на странице'],['Ctrl + P','Печать'],['Ctrl + + / −','Масштаб страницы'],['Ctrl + 0','Сбросить масштаб'],['F11','Полный экран']].map(([key,label])=>`<div><span>${tr(label)}</span><kbd>${key}</kbd></div>`).join('')}</div>`}
let loadedWallpaperVersion=-1;
function applyAppearance(){const s=state.settings,colors={violet:'#bc9ffa',ocean:'#85bdf5',forest:'#8ad4b2',rose:'#efa3c3',amber:'#efc28b'};document.body.dataset.colorTheme=s.colorTheme;document.body.dataset.wallpaper=s.wallpaper;document.body.classList.toggle('show-bookmark-bar',!!s.bookmarksBar);const lightColors={violet:'#7351cb',ocean:'#2763a6',forest:'#24795a',rose:'#ab356c',amber:'#966324'};const palette=document.body.classList.contains('light')?lightColors:colors;document.body.style.setProperty('--accent',s.colorTheme==='custom'?s.customAccent:palette[s.colorTheme]||palette.violet);document.body.style.setProperty('--wallpaper-dim',String((s.wallpaperDim??45)/100));document.body.style.setProperty('--reader-scale',String(Math.pow(1.2,current()?.zoomLevel||0)));
 if(loadedWallpaperVersion!==state.wallpaperVersion){const requested=state.wallpaperVersion;loadedWallpaperVersion=requested;command('wallpaper-data').then(data=>{if(requested!==state.wallpaperVersion)return;document.body.style.setProperty('--home-image',typeof data==='string'&&data.startsWith('data:image/jpeg;base64,')?'url("'+data+'")':'none')})}
}
function renderBookmarkBar(){const root=$('#bookmark-bar');if(!root)return;const key=JSON.stringify([state.bookmarks,language()]);if(root.dataset.key===key)return;root.dataset.key=key;root.innerHTML=state.bookmarks.length?state.bookmarks.slice(0,18).map(b=>`<button class="bookmark-bar-item" data-url="${esc(b.url)}" title="${esc(b.url)}">${icon('bookmark')}<span>${esc(b.title)}</span></button>`).join(''):`<button class="text-button" data-panel="bookmarks">${icon('bookmark')} ${tr('Добавляй страницы звездой в адресной строке.')}</button>`}
function bindFeatureForms(root){const browser=root.querySelector('#external-browser');if(browser)browser.onchange=e=>command('appearance',{externalBrowser:e.target.value});const color=root.querySelector('#custom-accent');if(color)color.onchange=e=>command('appearance',{colorTheme:'custom',customAccent:e.target.value});const dim=root.querySelector('#wallpaper-dim');if(dim){dim.oninput=e=>document.body.style.setProperty('--wallpaper-dim',String(Number(e.target.value)/100));dim.onchange=e=>command('appearance',{wallpaperDim:Number(e.target.value)})}const query=root.querySelector('#tab-query');if(query){query.oninput=e=>{tabQuery=e.target.value;root.querySelector('#tab-results').innerHTML=tabRows()};query.focus()}}
async function featureClick(button){const d=button.dataset;
 if(d.themeMode){await command('appearance',{theme:d.themeMode});return true}if(d.colorTheme){await command('appearance',{colorTheme:d.colorTheme});return true}if(d.wallpaper){await command('appearance',{wallpaper:d.wallpaper});return true}
 if(d.googleService){const result=await command('open-google',d.googleService);if(result)toast(tr('Сервис открыт в браузере.')+' '+result.browser);return true}
 if(d.selectTab){await command('select',Number(d.selectTab));await command('panel',null);return true}if(d.closeTab){await command('close-tab',Number(d.closeTab));return true}return false;
}

window.veyra.onFindResult(result=>{if($('#find-count'))$('#find-count').textContent=result.matches?result.active+' / '+result.matches:tr('Ничего не найдено.')});

matchMedia('(prefers-color-scheme: light)').addEventListener('change',()=>{if(state?.settings.theme==='system')render(state)});

function googleView(blocked=false){return externalGoogleView(blocked)}
function darkView(){const host=webURL(current()?.url)?new URL(current().url).hostname:'',s={enabled:state.settings.autoDark,brightness:100,contrast:100,...state.settings.darkSites[host]};return `<form id="dark-form">${toggle('autoDark','Auto Dark Mode','Для всех сайтов по умолчанию.')}<p class="note">Собственная тёмная тема сайта сохраняется. Перекраска применяется к светлым страницам; изображения и видео не меняются.</p>${host?`<h3>${esc(host)}</h3><label class="setting"><strong>Включить для сайта</strong><input type="checkbox" name="enabled" ${s.enabled?'checked':''}></label><label class="field">Яркость<input type="range" name="brightness" min="60" max="130" value="${s.brightness}"></label><label class="field">Контраст<input type="range" name="contrast" min="70" max="140" value="${s.contrast}"></label>`:'<p class="note">Открой сайт для индивидуальной настройки.</p>'}<button class="primary" type="submit">Применить</button></form>`}
function shortcutsView(){return `<p class="sub">Добавь свои сайты. Пустой список оставляет главную минимальной.</p>${state.settings.shortcuts.map(x=>`<div class="shortcut-editor"><strong class="user-shortcut-title">${esc(x.title)}</strong><button class="small-icon" data-shortcut-image="${x.id}" title="Выбрать изображение">${icon('upload')}</button><button class="small-icon" data-shortcut-delete="${x.id}" title="Удалить">${icon('trash')}</button><form class="shortcut-edit-form"><input type="hidden" name="id" value="${x.id}"><input name="title" value="${esc(x.title)}" maxlength="60" required><input name="url" type="url" value="${esc(x.url)}" required><button class="secondary" type="submit">Сохранить</button></form></div>`).join('')}<form class="shortcut-edit-form"><h3>Добавить сайт</h3><input name="title" placeholder="Название" maxlength="60" required><input name="url" type="url" placeholder="https://example.com" required><button class="primary" type="submit">Добавить</button></form>`}
function discordView(){return `<form id="discord-form">${toggle('discordEnabled','Discord Rich Presence','Статус на языке интерфейса Veyra.')}${toggle('discordShowDomain','Показывать домен сайта','Только домен активной обычной вкладки, без пути и параметров. Временные вкладки не передаются.')}${toggle('discordShowTime','Показывать время работы','Время с запуска браузера.')}<label class="field">Интервал обновления, секунд<input name="interval" type="number" min="15" max="3600" step="1" value="${state.settings.discordInterval}" required></label><p class="note">По умолчанию 60 секунд. Смена языка и скрытие домена применяются сразу.</p><label class="field">Application ID<input name="appId" value="${esc(state.settings.discordAppId)}" inputmode="numeric" pattern="[0-9]{17,22}" placeholder="Discord Application ID"></label><p class="note">Discord должен быть запущен на этом ПК.</p><p class="note">${esc(tr(({off:'Выключено',connecting:'Подключение',connected:'Подключено',unavailable:'Запусти Discord',error:'Ошибка подключения','application-id':'Укажи Application ID'})[state.discordStatus]||'Выключено'))}</p><button class="primary" type="submit">Сохранить</button></form>`}
function bindNewForms(root){const compatibility=root.querySelector('#compatibility-form');if(compatibility)compatibility.onsubmit=e=>{e.preventDefault();command('compatibility-save',compatibility.elements.domains.value.split(/\r?\n/))};const dark=root.querySelector('#dark-form');if(dark)dark.onsubmit=e=>{e.preventDefault();const f=new FormData(dark);command('dark-settings',{global:f.has('autoDark'),site:dark.elements.enabled?{enabled:f.has('enabled'),brightness:Number(f.get('brightness')),contrast:Number(f.get('contrast'))}:null})};for(const form of root.querySelectorAll('.shortcut-edit-form'))form.onsubmit=e=>{e.preventDefault();command('shortcut-save',Object.fromEntries(new FormData(form)))};const discord=root.querySelector('#discord-form');if(discord)discord.onsubmit=e=>{e.preventDefault();command('discord-settings',{enabled:discord.elements.discordEnabled.checked,appId:discord.elements.appId.value,showDomain:discord.elements.discordShowDomain.checked,showTime:discord.elements.discordShowTime.checked,interval:Number(discord.elements.interval.value)})}}

function compatibilityView(){return `<form id="compatibility-form"><p class="sub">Эти сайты автоматически открываются в профиле совместимости. Данные Chromium согласованы; параметры устройства не подделываются.</p><p class="note">Добавляй домены без https:// и пути, по одному в строке. Поддомены включаются автоматически. Изменения применятся при следующем открытии сайта.</p><label class="field">Домены<textarea name="domains" rows="10" spellcheck="false" placeholder="example.com">${esc(state.settings.compatibilityDomains.join('\n'))}</textarea></label><button class="primary" type="submit">Сохранить</button><p class="note">Аккаунты этого профиля хранятся отдельно. Список не гарантирует вход в Google и не отключает защиту от трекеров.</p></form>`}

const internalViews={'veyra://themes':['Темы и обои',customizeView],'veyra://shortcuts':['Ярлыки главной',shortcutsView],'veyra://compatibility':['Список совместимости',compatibilityView],'veyra://discord':['Discord Rich Presence',discordView],'veyra://dark':['Auto Dark Mode',darkView],'veyra://downloads':['Загрузки',downloadsView],'veyra://performance':['Производительность',performanceView],'veyra://privacy':['Приватность',privacyView]};

function downloadsView(){const limited=state.downloads.some(d=>d.status==='progress'&&d.limitMbps>0);const notice=limited?`<div class="download-limit-notice" role="status">${icon('gauge')}<div><strong>${esc(tr('Действует сетевой лимит'))}</strong><p>${esc(tr('Скорость ограничена в настройках производительности.'))}</p><button class="text-button" data-url="veyra://performance">${esc(tr('Изменить лимит'))}</button></div></div>`:'';return notice+(state.downloads.length?state.downloads.map(d=>`<div class="download"><div class="download-name">${icon('download')}<p>${esc(d.name)}</p></div><small>${d.status==='completed'?'Готово':d.status==='cancelled'?'Отменено':d.status==='interrupted'?'Прервано':(d.received/1048576).toFixed(1)+' / '+(d.total/1048576).toFixed(1)+' МБ'}</small>${d.status==='progress'&&d.limitMbps>0?`<p class="download-limit-label">${icon('gauge')} ${esc(tr('Сетевой лимит'))}: ${esc(Number(d.limitMbps).toLocaleString(language()))} ${esc(tr('Мбит/с'))}</p>`:''}${d.status==='progress'?`<progress value="${d.received}" max="${d.total||1}"></progress>`:''}${d.status==='completed'?`<button class="secondary wide" data-reveal-file="${esc(d.id)}">${icon('folder')} Показать в папке</button>`:''}</div>`).join(''):`<div class="empty">${icon('download')}<p>Загрузки появятся здесь.</p></div>`)}

function renderClipboard(){const dialog=$('#clipboard-dialog'),prompt=state.clipboardPrompt;if(!prompt){if(dialog.open)dialog.close();$('#clipboard-preview').textContent='';dialog.dataset.request='';return}if(dialog.dataset.request===prompt.id)return;dialog.dataset.request=prompt.id;$('#clipboard-origin').textContent=prompt.origin;$('#clipboard-preview').textContent=prompt.preview;$('#clipboard-length').textContent=prompt.length>prompt.preview.length?tr('Показано начало текста. Всего символов: ')+prompt.length:'';if(!dialog.open)dialog.showModal();$('#clipboard-cancel').focus()}
function respondClipboard(allow){if(state?.clipboardPrompt)command('clipboard-response',{id:state.clipboardPrompt.id,allow})}
$('#clipboard-cancel').onclick=$('#clipboard-cancel-x').onclick=()=>respondClipboard(false);$('#clipboard-allow').onclick=()=>respondClipboard(true);$('#clipboard-dialog').addEventListener('cancel',e=>{e.preventDefault();respondClipboard(false)});

let accountEmail='';
function accountField(name,title,type='text',extra=''){return `<label class="field">${title}<input name="${name}" type="${type}" ${name==='email'?`value="${esc(accountEmail)}" autocomplete="username" maxlength="254"`:''} ${extra} required></label>`}
function accountPassword(name='password',title='Пароль аккаунта'){return accountField(name,title,'password','autocomplete="off" minlength="12" maxlength="72"')}
function syncView(){return `<div class="page narrow sync-page"><h1>Аккаунт Veyra</h1><p class="sub">Синхронизация закладок между Windows и Android</p><div class="card"><p>Закладки шифруются на устройстве отдельной фразой. Используй одну фразу на всех устройствах. Восстановить её через сервер нельзя. Пароли, история и cookie не передаются.</p>${state.sync.signedIn?`<p>${esc(state.sync.email)}</p><div class="actions"><button id="sync-logout" class="secondary">Выйти</button><button id="sync-logout-all" class="secondary">Выйти на всех устройствах</button></div>`:`<form id="sync-login">${accountField('email','Email','email')}${accountPassword()}<p class="note">От 12 символов, до 72 байт UTF-8 (кириллица занимает больше одного байта).</p><div class="actions"><button class="primary" name="login">Войти</button><button class="secondary" name="signup">Создать аккаунт</button></div></form><details><summary>${icon('chevron')}Подтвердить email</summary><form id="sync-verify">${accountField('email','Email','email')}${accountPassword('password','Пароль аккаунта')}${accountField('code','Код из письма','text','inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8"')}<button class="primary">Подтвердить и войти</button></form></details><details><summary>${icon('chevron')}Забыли пароль?</summary><form id="sync-reset-request">${accountField('email','Email','email')}<button class="secondary">Отправить код восстановления</button></form><form id="sync-reset">${accountField('email','Email','email')}${accountField('code','Код из письма','text','inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8"')}${accountPassword('password','Новый пароль')}<button class="primary">Сохранить пароль и войти</button></form></details>`}</div>${state.sync.signedIn?`<form id="sync-transfer" class="card"><label class="field">Фраза шифрования<input type="password" name="passphrase" autocomplete="off" minlength="16" maxlength="1024" required></label><p class="note">Не менее 16 символов. Передача ручная. Получение объединяет закладки, сохраняя местные. Удаления между устройствами не распространяются.</p><div class="actions"><button class="primary" name="push" ${state.sync.busy?'disabled':''}>Отправить закладки</button><button class="secondary" name="pull" ${state.sync.busy?'disabled':''}>Получить закладки</button></div></form><details class="card"><summary>${icon('chevron')}Безопасность аккаунта</summary><form id="sync-password">${accountField('currentPassword','Текущий пароль','password','autocomplete="current-password" maxlength="72"')}${accountPassword('password','Новый пароль')}<p class="note">После смены пароля потребуется войти заново на всех устройствах.</p><button class="secondary">Сменить пароль</button></form><form id="sync-delete"><h3>Удалить аккаунт</h3><p>Будут удалены аккаунт и его облачные копии. Местные закладки сохранятся.</p>${accountField('currentPassword','Текущий пароль','password','autocomplete="current-password" maxlength="72"')}<button class="danger">Удалить аккаунт</button></form></details>`:''}<p id="sync-feedback" role="status"></p></div>`}
document.addEventListener('submit',async e=>{const form=e.target;if(!['sync-login','sync-transfer','sync-verify','sync-reset-request','sync-reset','sync-password','sync-delete'].includes(form.id))return;e.preventDefault();const name=e.submitter?.name,payload=Object.fromEntries(new FormData(form));if(payload.email)accountEmail=payload.email;let action=form.id;if(action==='sync-login')action=name==='signup'?'sync-signup':'sync-login';if(action==='sync-transfer')action=name==='push'?'sync-push':'sync-pull';const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);const result=await command(action,payload);buttons.forEach(b=>b.disabled=false);if(result?.mfa_required){let label=form.querySelector('[data-mfa-prompt]');if(!label){label=document.createElement('label');label.className='field';label.dataset.mfaPrompt='';label.textContent=ws('Код из приложения или резервный код','Authenticator code or recovery code');const input=document.createElement('input');input.name='mfa_code';input.autocomplete='one-time-code';input.maxLength=32;input.required=true;label.append(input);form.querySelector('button').before(label)}label.querySelector('input').focus();return}if(result){form.reset();const messages={'sync-signup':'Код отправлен. Открой «Подтвердить email» и введи код из письма.','sync-reset-request':'Код восстановления отправлен. Проверь почту и папку «Спам».','sync-push':'Закладки отправлены.','sync-pull':'Закладки объединены.','sync-password':'Пароль изменён. Войди снова.','sync-delete':'Аккаунт удалён.'};toast(messages[action]||'Вход выполнен.');contentKey='';renderContent();if(action==='sync-signup')$('#sync-verify')?.closest('details')?.setAttribute('open','')}});
document.addEventListener('click',async e=>{const button=e.target.closest('#sync-logout,#sync-logout-all');if(button){await command(button.id);contentKey='';renderContent()}});


document.addEventListener('click',async e=>{const check=e.target.closest('#check-updates'),download=e.target.closest('#download-update');if(check){check.disabled=true;const result=await command('update-check');check.disabled=false;if(result){const status=$('#update-result');if(status)status.textContent=result.newer?'Доступна версия '+result.version:'Установлена актуальная версия';const button=$('#download-update');if(button)button.hidden=!result.newer}}if(download){download.disabled=true;const ok=await command('update-download');download.disabled=false;if(ok)toast('Сборка проверена и сохранена.')}});

function renderAppDialog(){const el=$('#app-dialog'),prompt=state.appDialog;if(!prompt){if(el.open)el.close();el.dataset.id='';return}if(el.dataset.id===prompt.id)return;el.dataset.id=prompt.id;$('#app-dialog-title').textContent=tr(prompt.title);$('#app-dialog-origin').textContent=prompt.origin||'';$('#app-dialog-message').textContent=tr(prompt.message);$('#app-dialog-input-label').hidden=prompt.type!=='prompt';$('#app-dialog-input').value=prompt.defaultText||'';$('#app-dialog-cancel').hidden=prompt.type==='alert';el.showModal();(prompt.type==='prompt'?$('#app-dialog-input'):prompt.type==='alert'?$('#app-dialog-accept'):$('#app-dialog-cancel')).focus()}
function answerAppDialog(allow){const id=state.appDialog?.id;if(id)command('app-dialog-response',{id,allow,text:$('#app-dialog-input').value})}
$('#app-dialog-accept').onclick=()=>answerAppDialog(true);$('#app-dialog-cancel').onclick=()=>answerAppDialog(false);$('#app-dialog').addEventListener('cancel',e=>{e.preventDefault();answerAppDialog(false)});

$('#keep-awake').onclick=()=>command('keep-awake');$('#fake-presence').onclick=()=>command('fake-presence');

$('#default-banner-set').onclick=()=>command('default-browser');$('#default-banner-close').onclick=()=>command('dismiss-default-prompt');
